# gen-cats.ps1 - country-category hubs (sources common + hub builders).
. "$PSScriptRoot/gen-common.ps1"
. "$PSScriptRoot/gen-hubs.ps1" | Out-Null
function GPrice($c,$d,$m,$f){ return "From " + (Fmt-Money (Price-Pair $c $d $m $f)[0]) }

