 @("/tanzania-safari-from-zanzibar/3-day-safari-from-zanzibar/","3-Day Safari from Zanzibar","3 days | Nyerere + walking",(GPrice "Tanzania" 3 1.0 350),"River, road and foot in three days."),
 @("/tanzania-safari-from-zanzibar/5-day-safari-from-zanzibar/","5-Day Safari from Zanzibar","5 days | Serengeti + crater",(GPrice "Tanzania" 5 1.0 350),"The real northern circuit, flown."),
